argv:
query=query($owner: String!, $repo: String!, $p0: String!, $p1: String!) {
  repository(owner: $owner, name: $repo) {
    p0: pullRequests(headRefName: $p0, first: 10, orderBy: {field: CREATED_AT, direction: DESC}) { totalCount nodes { number url title body isCrossRepository baseRefName headRefOid mergeable labels(first: 20) { nodes { name } } state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } } }
    p1: pullRequests(headRefName: $p1, first: 10, orderBy: {field: CREATED_AT, direction: DESC}) { totalCount nodes { number url title body isCrossRepository baseRefName headRefOid mergeable labels(first: 20) { nodes { name } } state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } } }
  }
}
